// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }

    function testFuzz_property(uint256 initialBalance) public {
        vm.assume(initialBalance > 0);
        vm.assume(initialBalance <= address(c).balance + 1e18 ether);

        vm.deal(address(c), initialBalance);

        address recipient = address(uint160(uint256(keccak256(abi.encodePacked("recipient")))));

        c.withdrawAll(recipient);

        assertTrue(address(c).balance == 0);
    }
}
